    /// </summary>
    private JsonNode SketchCreate(JsonElement root)
    {
        AssertIsObject(root);
        var plane = RequirePlane(root, "plane");
        var name = GetOptionalString(root, "name");

        SketchCreateImpl(plane, name);

        var result = new JsonObject();
        result["sketch"] = new JsonObject();
        result["sketch"]!.AsObject()["id"] = GetNextId(name); // remove name when there is none
        result["sketch"]!.AsObject()["name"] = name;
        return result;
    }

    /// <summary>
    /// Creates a new sketch attached to a planar face. Returns sketchId and the derived sketch plane. Note: face is resolved via Selector (expected single face).
    /// </summary>
    private JsonNode SketchCreateOnFace(JsonElement root)
    {
        AssertIsObject(root);
        var face = RequireProperty(root, "face");
        var point = GetOptionalPoint3D(root, "point", GeoPoint.Invalid);
        var xAxis = GetOptionalVector3D(root, "xAxis", GeoVector.Invalid);
        var name = GetOptionalString(root, "name");

        SketchCreateOnFaceImpl(face, point, xAxis, name);

        var result = new JsonObject();
        result["sketch"] = new JsonObject();
        result["sketch"]!.AsObject()["id"] = GetNextId(name); // remove name when there is none
        result["sketch"]!.AsObject()["name"] = name;
        result["plane"] = null; // TODO
        return result;
    }

    /// <summary>
    /// Computes the closest orthogonal foot point of a given point onto a curve in a sketch.
    /// </summary>
    private JsonNode SketchFootPointOnCurve(JsonElement root)
    {
        AssertIsObject(root);
        var sketch = RequireObjectRef<Sketch>(root, "sketch");;
        var point = RequirePoint2D(root, "point");
        var curve = RequireProperty(root, "curve");
        var mode = GetOptionalString(root, "mode");
        var clamp = GetOptionalBool(root, "clamp", false);
        var name = GetOptionalString(root, "name");
        var captured = GetOptional(root, "captured");

        SketchFootPointOnCurveImpl(sketch, point, curve, mode, clamp, name, captured);

        return new JsonObject();
    }

    /// <summary>
    /// Returns vertices of sketch geometry in sketch coordinates (2D). Vertices are derived from the topology of the selected sketch entities/regions (e.g., polycurve/rectangle/ngon vertices, arc/line endpoints, and region boundary vertices after boolean/offset operations). If 'sketchGeometry' is omitted, all eligible entities in the sketch are processed. If 'name' is provided, the resulting vertex set is stored in the workspace under this name. If 'suffix' is true, individual vertices are also stored as workspace points named &lt;base&gt;_&lt;i&gt; (0-based), where &lt;base&gt; is 'name'. The operation may return multiple disjoint vertex loops; vertices are returned in a deterministic order per loop as provided by the kernel.
    /// </summary>
    private JsonNode SketchGetVertices(JsonElement root)
    {
        AssertIsObject(root);
        var sketch = RequireObjectRef<Sketch>(root, "sketch");;
        var sketchGeometry = GetOptional(root, "sketchGeometry");
        var name = GetOptionalString(root, "name");
        var suffix = GetOptionalBool(root, "suffix", false);
        var includeEndpoints = GetOptionalBool(root, "includeEndpoints", true);
        var unique = GetOptionalBool(root, "unique", false);
        var tolerance = GetOptionalDouble(root, "tolerance", double.NaN);

        SketchGetVerticesImpl(sketch, sketchGeometry, name, suffix, includeEndpoints, unique, tolerance);

        var result = new JsonObject();
        result["loops"] = new JsonArray();
        result["vertexCount"] = null; // TODO
        result["captured"] = new JsonObject();
        result["captured"]!.AsObject()["setName"] = null; // TODO
        result["captured"]!.AsObject()["vertexNames"] = new JsonArray();
        return result;
    }

    /// <summary>
    /// Computes intersection points between two sketch geometries.
    /// </summary>
    private JsonNode SketchIntersections(JsonElement root)
    {
        AssertIsObject(root);
        var sketch = RequireObjectRef<Sketch>(root, "sketch");;
        var a = RequireProperty(root, "a");
        var b = RequireProperty(root, "b");
        var mode = GetOptionalString(root, "mode");
        var tolerance = GetOptionalDouble(root, "tolerance", double.NaN);
        var name = GetOptionalString(root, "name");
        var suffix = GetOptionalBool(root, "suffix", true);

        SketchIntersectionsImpl(sketch, a, b, mode, tolerance, name, suffix);

        return new JsonObject();
    }

    /// <summary>
    /// Offsets sketch geometry by a given signed distance. Closed inputs produce parallel contours (region offsets). Open inputs produce equidistant curves. For open curves, positive distance offsets to the right side of the curve parameter direction, negative distance to the left side. If 'makeRegion' is true and the input is open, the tool attempts to create a closed region by combining the original curve and its offset (connecting corresponding end points). The operation may produce multiple disjoint results, including regions with holes, depending on the input geometry and distance. If 'sketchGeometry' is omitted, all eligible entities in the sketch are offset.
    /// </summary>
    private JsonNode SketchOffset(JsonElement root)
    {
        AssertIsObject(root);
        var sketch = RequireObjectRef<Sketch>(root, "sketch");;
        var sketchGeometry = GetOptional(root, "sketchGeometry");
        var distance = RequireDouble(root, "distance");
        var joinType = GetOptionalString(root, "joinType");
        var miterLimit = GetOptionalDouble(root, "miterLimit", double.NaN);
        var makeRegion = GetOptionalBool(root, "makeRegion", false);
        var capType = GetOptionalString(root, "capType");
        var name = GetOptionalString(root, "name");

        SketchOffsetImpl(sketch, sketchGeometry, distance, joinType, miterLimit, makeRegion, capType, name);

        var result = new JsonObject();
        result["sketchGeometry"] = new JsonArray();
        result["createdCount"] = null; // TODO
        return result;
    }

    /// <summary>
    /// Creates a line perpendicular to a given line through a specified point.
    /// </summary>
    private JsonNode SketchPerpendicularThrough(JsonElement root)
    {
        AssertIsObject(root);
        var sketch = RequireObjectRef<Sketch>(root, "sketch");;
        var line = RequireProperty(root, "line");
        var point = RequirePoint2D(root, "point");
        var length = GetOptionalDouble(root, "length", 1);
        var name = GetOptionalString(root, "name");

        SketchPerpendicularThroughImpl(sketch, line, point, length, name);

        return new JsonObject();
    }

    /// <summary>
    /// Rounds (fillets) vertices of sketch entities. If entity is omitted, applies to all eligible entities in the sketch. Vertex selection can be done by proximity points (2D) or by vertex indices (for entities with an ordered vertex list such as polycurve/rectangle/ngon). If neither points nor indices are provided, all vertices are rounded. If name is omitted, the operation overwrites the original entity (same name as the source). If name is provided, a new entity is created and the original remains.
    /// </summary>
    private JsonNode SketchRoundVertices(JsonElement root)
    {
        AssertIsObject(root);
        var sketch = RequireObjectRef<Sketch>(root, "sketch");;
        var entity = GetOptional(root, "entity");
        var radius = RequireDouble(root, "radius");
        var nearPoints = GetOptional(root, "nearPoints");
        var indices = GetOptional(root, "indices");
        var tolerance = GetOptionalDouble(root, "tolerance", double.NaN);
        var name = GetOptionalString(root, "name");

        SketchRoundVerticesImpl(sketch, entity, radius, nearPoints, indices, tolerance, name);

        var result = new JsonObject();
        result["affectedCount"] = null; // TODO
        result["sketchGeometry"] = new JsonArray();
        return result;
    }

    /// <summary>
    /// Performs a boolean operation on solids. The first operand is the target (and defines the default name). The second operand can be a single solid or a list of solids. Does not modify inputs; returns a new solid. Supports automatic topology rebind (default: rebind=true) after the operation so that named faces/edges remain usable across boolean changes.
    /// </summary>
    private JsonNode SolidBoolean(JsonElement root)
    {
        AssertIsObject(root);
        var op = RequireString(root, "op");
        var a = RequireProperty(root, "a");
        var b = RequireProperty(root, "b");
        var name = GetOptionalString(root, "name");
        var rebind = GetOptionalBool(root, "rebind", true);
        var rebindTargets = GetOptional(root, "rebindTargets");

        SolidBooleanImpl(op, a, b, name, rebind, rebindTargets);

        var result = new JsonObject();
        result["solid"] = new JsonObject();
        result["solid"]!.AsObject()["id"] = GetNextId(name); // remove name when there is none
        result["solid"]!.AsObject()["name"] = name;
        return result;
    }

    /// <summary>
    /// Creates a box solid defined by an origin point and three edge lengths along a local coordinate system.
    /// </summary>
    private JsonNode SolidBox(JsonElement root)
    {
        AssertIsObject(root);
        var origin = RequirePoint3D(root, "origin");
        var axisX = GetOptionalVector3D(root, "axisX", GeoVector.Invalid);
        var axisY = GetOptionalVector3D(root, "axisY", GeoVector.Invalid);
        var sizeX = RequireDouble(root, "sizeX");
        var sizeY = RequireDouble(root, "sizeY");
        var sizeZ = RequireDouble(root, "sizeZ");
        var name = GetOptionalString(root, "name");

        SolidBoxImpl(origin, axisX, axisY, sizeX, sizeY, sizeZ, name);

        return new JsonObject();
    }

    /// <summary>
    /// Creates a capsule solid defined by two axis points and a radius.
