    /// <summary>
    /// Extrudes a profile into a new solid body. direction defaults to profile/sketch normal. The extrusion spans from offset to offset+length along direction. If pitch is provided, performs a helical (screw-like) extrusion around the axis. Returns the new solid. Optionally captures start/end faces and profile-edge loops as named sets. Note: profile is resolved via Selector (expected sketch geometry or sketch with closed loops).
    /// </summary>
    private JsonNode SolidExtrude(JsonElement root)
    {
        AssertIsObject(root);
        var profile = RequireProperty(root, "profile");
        var length = RequireDouble(root, "length");
        var direction = GetOptionalVector3D(root, "direction", GeoVector.Invalid);
        var name = GetOptionalString(root, "name");
        var offset = GetOptionalDouble(root, "offset", 0);
        var pitch = GetOptionalDouble(root, "pitch", 0);
        var capture = GetOptional(root, "capture");

        SolidExtrudeImpl(profile, length, direction, name, offset, pitch, capture);

        var result = new JsonObject();
        result["solid"] = new JsonObject();
        result["solid"]!.AsObject()["id"] = GetNextId(name); // remove name when there is none
        result["solid"]!.AsObject()["name"] = name;
        return result;
    }

    /// <summary>
    /// Creates a hollow cylindrical pipe solid.
    /// </summary>
    private JsonNode SolidPipe(JsonElement root)
    {
        AssertIsObject(root);
        var start = RequirePoint3D(root, "start");
        var end = RequirePoint3D(root, "end");
        var outerRadius = RequireDouble(root, "outerRadius");
        var innerRadius = RequireDouble(root, "innerRadius");
        var name = GetOptionalString(root, "name");

        SolidPipeImpl(start, end, outerRadius, innerRadius, name);

        return new JsonObject();
    }

    /// <summary>
    /// Revolves a planar profile around an axis to create a new solid body (revolve). angle can be full rotation or degrees. Returns the new solid. For partial revolves, start/end cap faces may be captured. Note: profile is resolved via Selector.
    /// </summary>
    private JsonNode SolidRotate(JsonElement root)
    {
        AssertIsObject(root);
        var profile = RequireProperty(root, "profile");
        var axis = RequireAxis3D(root, "axis");
        var angle = RequireAngle(root, "angle");
        var name = GetOptionalString(root, "name");
        var capture = GetOptional(root, "capture");

        SolidRotateImpl(profile, axis, angle, name, capture);

        var result = new JsonObject();
        result["solid"] = new JsonObject();
        result["solid"]!.AsObject()["id"] = GetNextId(name); // remove name when there is none
        result["solid"]!.AsObject()["name"] = name;
        return result;
    }

    /// <summary>
    /// Creates a solid by connecting two closed sketch profiles with ruled surfaces. Corresponding points on the two profiles are connected by straight line segments. The profiles must be closed sketch geometries.
    /// </summary>
    private JsonNode SolidRuled(JsonElement root)
    {
        AssertIsObject(root);
        var profile1 = RequireProperty(root, "profile1");
        var profile2 = RequireProperty(root, "profile2");
        var synchronization = GetOptionalString(root, "synchronization");
        var alignment = GetOptionalString(root, "alignment");
        var matchPoints1 = GetOptional(root, "matchPoints1");
        var matchPoints2 = GetOptional(root, "matchPoints2");
        var name = GetOptionalString(root, "name");

        SolidRuledImpl(profile1, profile2, synchronization, alignment, matchPoints1, matchPoints2, name);

        return new JsonObject();
    }

    /// <summary>
    /// Creates a sphere solid. The sphere can be defined using different equivalent parameter sets.
    /// </summary>
    private JsonNode SolidSphere(JsonElement root)
    {
        AssertIsObject(root);
        var center = GetOptionalPoint3D(root, "center", GeoPoint.Invalid);
        var radius = GetOptionalDouble(root, "radius", double.NaN);
        var points = GetOptional(root, "points");
        var name = GetOptionalString(root, "name");

        SolidSphereImpl(center, radius, points, name);

        return new JsonObject();
    }

    /// <summary>
    /// Sweeps a profile along a path curve to create a new solid body. Path is a 3D curve or polycurve. Orientation defaults to 'follow' (Frenet/transport). Returns the new solid. Optionally captures start/end faces and profile-edge loops. Note: profile is resolved via Selector. Note: path is resolved via Selector (expected single path/curve).
    /// </summary>
    private JsonNode SolidSweep(JsonElement root)
    {
        AssertIsObject(root);
        var profile = RequireProperty(root, "profile");
        var path = RequireProperty(root, "path");
        var orientation = GetOptionalString(root, "orientation");
        var name = GetOptionalString(root, "name");
        var capture = GetOptional(root, "capture");

        SolidSweepImpl(profile, path, orientation, name, capture);

        var result = new JsonObject();
        result["solid"] = new JsonObject();
        result["solid"]!.AsObject()["id"] = GetNextId(name); // remove name when there is none
        result["solid"]!.AsObject()["name"] = name;
        return result;
    }

    /// <summary>
    /// Creates a torus solid defined by center, axis, major radius and minor radius.
    /// </summary>
    private JsonNode SolidTorus(JsonElement root)
    {
        AssertIsObject(root);
        var center = RequirePoint3D(root, "center");
        var axis = RequireVector3D(root, "axis");
        var majorRadius = RequireDouble(root, "majorRadius");
        var minorRadius = RequireDouble(root, "minorRadius");
        var name = GetOptionalString(root, "name");

        SolidTorusImpl(center, axis, majorRadius, minorRadius, name);

        return new JsonObject();
    }

    /// <summary>
    /// Creates a NURBS surface from control points, knot vectors and optional weights. The resulting surface can be used as an unbounded carrier surface for later operations such as solid splitting.
    /// </summary>
    private JsonNode SurfaceNurbs(JsonElement root)
    {
        AssertIsObject(root);
        var degreeU = RequireInteger(root, "degreeU");
        var degreeV = RequireInteger(root, "degreeV");
        var controlPoints = RequireProperty(root, "controlPoints");
        var uKnots = RequireProperty(root, "uKnots");
        var vKnots = RequireProperty(root, "vKnots");
        var weights = GetOptional(root, "weights");
        var uPeriodic = GetOptionalBool(root, "uPeriodic", false);
        var vPeriodic = GetOptionalBool(root, "vPeriodic", false);
        var name = GetOptionalString(root, "name");

        SurfaceNurbsImpl(degreeU, degreeV, controlPoints, uKnots, vKnots, weights, uPeriodic, vPeriodic, name);

        return new JsonObject();
    }

    /// <summary>
    /// Creates a parametric surface from three expressions x(u,v), y(u,v), z(u,v) over a rectangular parameter domain. The surface is internally approximated by a NURBS surface and can be used as an unbounded carrier surface for later operations such as solid splitting.
    /// </summary>
    private JsonNode SurfaceParametric(JsonElement root)
    {
        AssertIsObject(root);
        var degreeU = GetOptionalInteger(root, "degreeU", 3);
        var degreeV = GetOptionalInteger(root, "degreeV", 3);
        var approximation = RequireProperty(root, "approximation");
        var name = GetOptionalString(root, "name");

        SurfaceParametricImpl(degreeU, degreeV, approximation, name);

        return new JsonObject();
    }

