        AssertIsObject(root);

        SystemGetInfoImpl();

        var result = new JsonObject();
        result["toolsetId"] = null; // TODO
        result["toolsetVersion"] = null; // TODO
        result["schemaVersion"] = null; // TODO
        result["generatedAt"] = null; // TODO
        result["toolsHash"] = null; // TODO
        return result;
    }

    /// <summary>
    /// Translates one or more objects by a 3D vector. If copy=true, returns new objects; otherwise modifies originals. Returned objects are references to moved/copied objects. When copy=true, the server can also copy named topology references (copyNamed=true) and create new names using nameSuffix. Note: objects are resolved via Selector (may select one or many).
    /// </summary>
    private JsonNode TransformMove(JsonElement root)
    {
        AssertIsObject(root);
        var objects = RequireProperty(root, "objects");
        var delta = RequireVector3D(root, "delta");
        var name = GetOptionalString(root, "name");
        var copySuffix = GetOptionalString(root, "copySuffix");

        TransformMoveImpl(objects, delta, name, copySuffix);

        var result = new JsonObject();
        result["objects"] = new JsonArray();
        return result;
    }

    /// <summary>
    /// Reflects (mirrors) one or more objects across a plane. If copy=true, returns new objects; otherwise modifies originals. When copy=true, the server can also copy named topology references (copyNamed=true) and create new names using nameSuffix. Note: objects are resolved via Selector (may select one or many).
    /// </summary>
    private JsonNode TransformReflect(JsonElement root)
    {
        AssertIsObject(root);
        var objects = RequireProperty(root, "objects");
        var plane = GetOptionalPlane(root, "plane", Plane.Invalid);
        var axis3D = GetOptionalAxis3D(root, "axis3D", Axis.InvalidAxis);
        var axis2D = GetOptionalAxis2D(root, "axis2D", Axis2D.InvalidAxis);
        var name = GetOptionalString(root, "name");
        var copySuffix = GetOptionalString(root, "copySuffix");

        TransformReflectImpl(objects, plane, axis3D, axis2D, name, copySuffix);

        var result = new JsonObject();
        result["objects"] = new JsonArray();
        return result;
    }

    /// <summary>
    /// Rotates one or more objects around an axis by a given angle. If 'name' is omitted, the selected objects are rotated in place and keep their names. If 'name' is provided, copies are created, rotated, and captured as a named set. When multiple objects are copied, individual result names are derived from the original names by appending 'nameSuffix'.
    /// </summary>
    private JsonNode TransformRotate(JsonElement root)
    {
        AssertIsObject(root);
        var objects = RequireProperty(root, "objects");
        var axis = RequireAxis3D(root, "axis");
        var angle = RequireAngle(root, "angle");
        var name = GetOptionalString(root, "name");
        var copySuffix = GetOptionalString(root, "copySuffix");

        TransformRotateImpl(objects, axis, angle, name, copySuffix);

        var result = new JsonObject();
        result["objects"] = new JsonArray();
        return result;
    }

    /// <summary>
    /// Scales one or more objects about an origin. Provide either uniform factor or non-uniform factors (x,y,z). If copy=true, returns new objects; otherwise modifies originals. When copy=true, the server can also copy named topology references (copyNamed=true) and create new names using nameSuffix. Note: objects are resolved via Selector (may select one or many).
    /// </summary>
    private JsonNode TransformScale(JsonElement root)
    {
        AssertIsObject(root);
        var objects = RequireProperty(root, "objects");
        var origin = RequirePoint3D(root, "origin");
        var factor = GetOptionalDouble(root, "factor", double.NaN);
        var factors = GetOptional(root, "factors");
        var name = GetOptionalString(root, "name");
        var copySuffix = GetOptionalString(root, "copySuffix");

        TransformScaleImpl(objects, origin, factor, factors, name, copySuffix);

        var result = new JsonObject();
        result["objects"] = new JsonArray();
        return result;
    }

    /// <summary>
    /// Begins an undo frame. All subsequent committed changes until undo.end are grouped into one undo step. Returns undoFrameId.
    /// </summary>
    private JsonNode UndoBegin(JsonElement root)
    {
        AssertIsObject(root);
        var label = RequireString(root, "label");

        UndoBeginImpl(label);

        var result = new JsonObject();
        result["undoFrameId"] = null; // TODO
        return result;
    }

    /// <summary>
    /// Cancels an undo frame started with undo.begin, rolling back all changes in that frame.
    /// </summary>
    private JsonNode UndoCancel(JsonElement root)
    {
        AssertIsObject(root);
        var undoFrameId = RequireString(root, "undoFrameId");

        UndoCancelImpl(undoFrameId);

        return new JsonObject();
    }

    /// <summary>
    /// Ends an undo frame started with undo.begin. If errors occurred, server may auto-cancel the frame.
    /// </summary>
    private JsonNode UndoEnd(JsonElement root)
    {
        AssertIsObject(root);
        var undoFrameId = RequireString(root, "undoFrameId");

        UndoEndImpl(undoFrameId);

        return new JsonObject();
    }

    /// <summary>
    /// Deletes one or more workspace objects (temporary objects not yet committed). Deleting a committed object is not allowed and returns E_INVALID_PARAMS. Note: objects are resolved via Selector (may select one or many).
    /// </summary>
    private JsonNode WorkspaceDelete(JsonElement root)
    {
        AssertIsObject(root);
        var objects = RequireProperty(root, "objects");

        WorkspaceDeleteImpl(objects);

        return new JsonObject();
    }

    /// <summary>
    /// Defines or updates a named workspace value. Optionally, the value can be marked as a user-editable parameter with UI metadata such as label, input type, limits, and choices.
    /// </summary>
    private JsonNode WorkspaceSet(JsonElement root)
    {
        AssertIsObject(root);
        var name = RequireString(root, "name");
        var value = RequireProperty(root, "value");
        var label = GetOptionalString(root, "label");
        var input = GetOptional(root, "input");

        WorkspaceSetImpl(name, value, label, input);

        var result = new JsonObject();
        result["name"] = name;
        return result;
    }

